 */

/* ===== src/tokens.css ===== */
/*
 * 清酒档案室 / SAKE ARCHIVE
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */
@font-face {
    font-family: "Zhuque Fangsong";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "LXGW WenKai";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/lxgwwenkai/lxgwwenkai.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --archive-mint-00: #f7fcfa;
    --archive-mint-10: #eef8f5;
    --archive-mint-20: #dfefeb;
    --archive-mint-30: #c5e2dc;
    --archive-paper: #f9f6ef;
    --archive-paper-warm: #fffaf5;
    --archive-pink: #f2c3c6;
    --archive-pink-soft: #f9e7e5;
    --archive-pink-deep: #c9656b;
    --archive-ink: #17201f;
    --archive-muted: #596a67;
    --archive-faint: #8da09c;
    --archive-aqua: #6cb9ad;
    --archive-info: #5a9f9a;
    --archive-success: #5f8f6d;
    --archive-warning: #b8874d;
    --archive-error: #b65b62;
    --archive-line: rgba(23, 32, 31, 0.72);
    --archive-line-soft: rgba(23, 32, 31, 0.25);
    --archive-shadow: 0 0.7rem 1.7rem rgba(66, 93, 88, 0.13);
    --archive-shadow-small: 0 0.3rem 0.8rem rgba(66, 93, 88, 0.12);
    --archive-radius: 0;
    --archive-gap-xs: 0.28rem;
    --archive-gap-sm: 0.55rem;
    --archive-gap-md: 0.9rem;
    --archive-gap-lg: 1.4rem;
    --archive-font-body: "Zhuque Fangsong", "Noto Serif CJK SC", "Noto Serif SC", "FangSong", "STFangsong", serif;
    --archive-font-quote: "LXGW WenKai", "KaiTi", "STKaiti", cursive;
    --archive-font-label: "Courier New", "Zhuque Fangsong", monospace;
    --archive-font-size-body: 1em;
    --archive-font-size-user: 1.02em;
    --archive-font-size-character: 1em;
    --archive-font-size-meta: 0.78em;
    --archive-font-size-input: 1em;
    --archive-top-label-width: clamp(7.4rem, 9vw, 9rem);
    --topBarBlockSize: 3.6rem;
    --bottomFormBlockSize: 8rem;
}

body {
    color: var(--archive-ink);
    background-color: var(--archive-mint-10);
    font-family: var(--archive-font-body);
}

/* ===== src/kernel/safety.css ===== */
/* 只含功能与状态保护，不决定主题构图。 */
#top-bar ::before,
#top-bar ::after,
#chat .mes ::before,
#chat .mes ::after,
#send_form ::before,
#send_form ::after {
    pointer-events: none;
}

:is(#top-bar, #chat, #send_form, .popup, #toast-container) :is(button, .menu_button, .interactable, input, textarea, select):focus-visible {
    outline: 2px solid var(--archive-pink-deep);
    outline-offset: 2px;
}

#send_form :is(#send_but, #mes_stop, #options_button, #mes_impersonate),
#top-bar .drawer-icon,
#chat .mes_buttons,
#chat :is(.swipe_left, .swipe_right, .swipes-counter) {
    opacity: 1;
    filter: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel) :is(input, textarea, select, button):disabled {
    color: var(--archive-muted);
    opacity: 0.7;
}

#chat .mes_text,
#chat .mes_block,
#chat .mes_block > :is(.ch_name, .mes_text, .mes_reasoning_details, .mes_media_wrapper, .mes_file_wrapper) {
    min-width: 0;
}

/* ===== src/kernel/scrollbars.css ===== */
/* 只隐藏滚动条外观；不改变 overflow、滚动容器或交互。 */
:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    #left-nav-panel,
    #left-nav-panel *,
    #right-nav-panel,
    #right-nav-panel *,
    #PersonaManagement,
    #PersonaManagement *,
    #completion_prompt_manager,
    #completion_prompt_manager *,
    .welcomePanel,
    .welcomePanel *,
    #send_form,
    #send_form *,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
) {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    #left-nav-panel,
    #left-nav-panel *,
    #right-nav-panel,
    #right-nav-panel *,
    #PersonaManagement,
    #PersonaManagement *,
    #completion_prompt_manager,
    #completion_prompt_manager *,
    .welcomePanel,
    .welcomePanel *,
    #send_form,
    #send_form *,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
)::-webkit-scrollbar {
    width: 0;
    height: 0;
}

/* ===== src/chat-layout.css ===== */
/*
 * 自定义外壳：archive-fullwidth
 * 结构门禁：已确认。桌面与手机均隐藏头像视觉节点并释放槽位，正文使用单列整宽。
 */
#chat {
    gap: clamp(1.2rem, 2.5vh, 2.4rem);
    padding: clamp(1.4rem, 3vw, 3.2rem) clamp(1rem, 3.2vw, 3.8rem) clamp(8.5rem, 14vh, 10rem);
    color: var(--archive-ink);
    background-color: var(--archive-mint-10);
    background-image:
        linear-gradient(rgba(255, 255, 255, 0.36), rgba(255, 255, 255, 0.36)),
        repeating-linear-gradient(0deg, rgba(55, 108, 99, 0.025) 0 1px, transparent 1px 5px);
    border: 0;
    box-shadow: none;
    text-shadow: none;
}

#chat::before {
    content: "SAKE ARCHIVE  /  清酒档案室  ·  CONVERSATION RECORD";
    align-self: stretch;
    padding: 0 0 0.65rem;
    color: var(--archive-muted);
    border-bottom: 0;
    font-family: var(--archive-font-label);
    font-size: 0.72em;
    letter-spacing: 0.22em;
}

#chat .mes {
    width: min(100%, 92rem);
    max-width: 92rem;
    margin: 0 auto;
    padding: 0;
    color: var(--archive-ink);
    background: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes[is_system="false"] {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
}

#chat .mes[is_system="false"] > .mesAvatarWrapper {
    display: none;
}

#chat .mes[is_system="false"] > .mes_block {
    grid-column: 1;
    width: 100%;
    min-width: 0;
    margin: 0;
    position: relative;
}

#chat .mes[is_user="true"] > .mes_block {
    min-height: 7.4rem;
    padding: 1.25rem 2rem 1.1rem 5.9rem;
    overflow: hidden;
    color: var(--archive-ink);
    background-color: var(--archive-pink);
    background-image: repeating-linear-gradient(0deg, rgba(255,255,255,0.13) 0 1px, transparent 1px 4px);
    border: 1px solid var(--archive-line);
    box-shadow: var(--archive-shadow-small);
}

#chat .mes[is_user="true"] > .mes_block::before {
    content: "ADMISSION\A TICKET";
    white-space: pre;
    position: absolute;
    inset: 0 auto 0 0;
    width: 4.3rem;
    display: grid;
    place-content: center;
    color: var(--archive-muted);
    border-right: 1px dashed var(--archive-line);
    font-family: var(--archive-font-label);
    font-size: 0.62em;
    line-height: 1.45;
    letter-spacing: 0.14em;
    text-align: center;
}

#chat .mes[is_user="true"] > .mes_block::after {
    content: "✣";
    position: absolute;
    right: 1rem;
    bottom: 0.7rem;
    color: var(--archive-pink-deep);
    font-size: 1.4em;
}

#chat .mes[is_user="false"][is_system="false"] > .mes_block {
    padding: 0 0.25rem 1.2rem;
    background: transparent;
    border-top: 1px solid var(--archive-line);
}

#chat .mes[is_user="false"][is_system="false"] > .mes_block::before {
    content: "CHARACTER RECORD  /  ARCHIVE ENTRY";
    display: block;
    padding: 0.5rem 0 0.8rem;
    color: var(--archive-muted);
    border-bottom: 0;
    font-family: var(--archive-font-label);
    font-size: 0.66em;
    letter-spacing: 0.14em;
}

#chat .mes .ch_name {
    min-height: 1.9rem;
    margin: 0;
    padding: 0.58rem 0 0.42rem;
    display: flex;
    align-items: center;
    gap: 0.65rem;
    color: var(--archive-ink);
    border-bottom: 0;
    font-family: var(--archive-font-body);
}

#chat .mes[is_user="true"] .ch_name {
    padding-top: 0;
}

#chat .mes .name_text {
    color: var(--archive-ink);
    font-size: 1.06em;
    font-weight: 400;
    letter-spacing: 0.08em;
}

#chat .mes .timestamp,
#chat .mes :is(.mesIDDisplay, .tokenCounterDisplay, .mes_timer) {
    color: var(--archive-muted);
    font-family: var(--archive-font-label);
    font-size: var(--archive-font-size-meta);
    letter-spacing: 0.08em;
}

#chat .mes .mes_buttons {
    margin-left: auto;
    color: var(--archive-ink);
    gap: 0.25rem;
    text-shadow: none;
}

#chat .mes .mes_button,
#chat .mes .mes_buttons .interactable {
    color: var(--archive-ink);
    filter: none;
    opacity: 1;
    border-bottom: 0;
    text-decoration: none;
    transition: color 140ms ease;
}

#chat .mes .mes_button:hover,
#chat .mes .mes_buttons .interactable:hover,
#chat .mes .mes_button:focus-visible,
#chat .mes .mes_buttons .interactable:focus-visible {
    color: var(--archive-pink-deep);
    filter: none;
    opacity: 1;
}

#chat .mes[is_system="true"],
#chat .mes.smallSysMes {
    width: min(100%, 68rem);
    padding: 0.7rem 1rem;
    color: var(--archive-muted);
    background: rgba(249, 246, 239, 0.78);
    border: 1px dashed var(--archive-line-soft);
    font-family: var(--archive-font-label);
    font-size: 0.86em;
}

#chat .mes_reasoning_details {
    margin: 0.8rem 0;
    color: var(--archive-ink);
    background: rgba(223, 239, 235, 0.8);
    border: 1px dashed var(--archive-aqua);
    border-radius: 0;
}

#chat .mes_reasoning_details > .mes_reasoning_summary,
#chat .mes_reasoning_details .mes_reasoning_header {
    margin: 0;
    padding: 0.52rem 0.72rem;
    color: var(--archive-ink);
    background: var(--archive-paper);
    border: 0;
    border-bottom: 0;
    border-radius: 0;
    box-shadow: none;
    font-family: var(--archive-font-label);
    font-size: 0.82em;
    letter-spacing: 0.06em;
}

#chat .mes_reasoning_details .mes_reasoning {
    padding: 0.7rem 0.85rem;
    color: var(--archive-muted);
    background: transparent;
    border: 0;
    border-radius: 0;
}

#chat :is(.swipe_left, .swipe_right, .swipes-counter) {
    color: var(--archive-muted);
    font-family: var(--archive-font-label);
    text-shadow: none;
}

#chat .mes_media_wrapper,
#chat .mes_file_wrapper {
    max-width: 100%;
    padding: 0.55rem;
    background: var(--archive-paper);
    border: 1px solid var(--archive-line-soft);
}

/* ===== src/full-text.css ===== */
/* 全文排版只负责正文语义；父级已经释放头像槽位。 */
#chat .mes_text {
    width: 100%;
    max-width: 72rem;
    margin: 0 auto;
    padding: 0.95rem 0 0;
    color: var(--archive-ink);
    font-family: var(--archive-font-body);
    font-size: var(--archive-font-size-body);
    font-weight: 400;
    line-height: 1.82;
    letter-spacing: 0.012em;
    text-align: left;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
    max-width: none;
    padding-top: 0.75rem;
    font-size: var(--archive-font-size-user);
    line-height: 1.72;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    font-size: var(--archive-font-size-character);
}

@media (min-width: 801px) {
    #chat .mes_text,
    #chat .mes[is_user="true"] .mes_text,
    #chat .mes[is_user="false"][is_system="false"] .mes_text {
        font-size: 1.12em;
    }
}

#chat .mes_text p {
    margin: 0 0 1em;
}

#chat .mes_text p:last-child {
    margin-bottom: 0;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    margin: 1.35em 0 0.65em;
    color: var(--archive-ink);
    font-family: var(--archive-font-body);
    font-weight: 400;
    line-height: 1.35;
    letter-spacing: 0.1em;
}

#chat .mes_text :is(h1, h2) {
    padding-bottom: 0.35em;
    border-bottom: 0;
}

#chat .mes_text :is(strong, b) {
    color: var(--archive-pink-deep);
    font-weight: 400;
    text-decoration: none;
}

#chat .mes_text em {
    color: var(--archive-muted);
}

#chat .mes_text blockquote {
    margin: 1.1em 0;
    padding: 0.82em 1.1em;
    color: var(--archive-ink);
    background: var(--archive-paper-warm);
    border-left: 3px double var(--archive-pink-deep);
    border-bottom: 0;
    font-family: var(--archive-font-quote);
    font-size: 0.97em;
    font-style: normal;
    line-height: 1.85;
    letter-spacing: 0.035em;
}

#chat .mes_text :is(ul, ol) {
    margin: 0.9em 0;
    padding-left: 1.5em;
}

#chat .mes_text li::marker {
    color: var(--archive-pink-deep);
    font-family: var(--archive-font-label);
}

#chat .mes_text a {
    color: #397f77;
    text-decoration: none;
    border-bottom: 0;
}

#chat .mes_text :is(code, kbd) {
    color: var(--archive-ink);
    background: var(--archive-paper);
    border: 1px solid var(--archive-line-soft);
    border-radius: 0;
    font-family: var(--archive-font-label);
    font-size: 0.88em;
}

#chat .mes_text pre {
    max-width: 100%;
    padding: 1rem;
    overflow-x: auto;
    color: var(--archive-ink);
    background: var(--archive-paper);
    border: 1px solid var(--archive-line);
    border-radius: 0;
}

#chat .mes_text table {
    width: 100%;
    max-width: 100%;
    border-collapse: collapse;
    background: rgba(249, 246, 239, 0.78);
}

#chat .mes_text :is(th, td) {
    padding: 0.58em 0.72em;
    border: 1px solid var(--archive-line-soft);
    text-align: left;
}

#chat .mes_text th {
    color: var(--archive-ink);
    background: var(--archive-mint-20);
    font-weight: 400;
    letter-spacing: 0.08em;
}

#chat .mes_text hr {
    margin: 1.5em 0;
    border: 0;
    border-top: 1px dashed var(--archive-line);
}

#chat .mes_text img,
#chat .mes_text video {
    max-width: 100%;
    height: auto;
    border: 0.5rem solid var(--archive-paper);
    box-shadow: 0 0 0 1px var(--archive-line), var(--archive-shadow-small);
}

/* ===== src/windows/top-bar.css ===== */
/* P3 档案室索引栏：保留九项标签，只缩短高度；不改展开抽屉内容几何。 */
body #top-bar {
    width: 100%;
    max-width: none;
    height: var(--topBarBlockSize);
    margin: 0;
    color: var(--archive-ink);
    background: rgba(247, 252, 250, 0.97);
    border-bottom: 0;
    box-shadow: none;
    backdrop-filter: none;
}

#top-bar::before {
    content: "清酒档案室\A SAKE ARCHIVE";
    white-space: pre;
    position: absolute;
    left: clamp(0.65rem, 1.4vw, 1.4rem);
    top: 0.55rem;
    width: calc(var(--archive-top-label-width) - 1rem);
    color: var(--archive-ink);
    font-family: var(--archive-font-body);
    font-size: 0.7em;
    line-height: 1.05;
    letter-spacing: 0.07em;
    pointer-events: none;
}

body #top-settings-holder {
    width: 100%;
    max-width: none;
    height: var(--topBarBlockSize);
    margin: 0;
    padding-left: var(--archive-top-label-width);
    box-sizing: border-box;
    color: var(--archive-ink);
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > [class~="drawer-toggle"] {
    width: 100%;
    height: 100%;
    min-width: 0;
    padding: 0.22rem 0.12rem 0.18rem;
    display: grid;
    grid-template-rows: 1.15rem 1fr;
    place-items: center;
    color: var(--archive-ink);
    background: transparent;
    border-left: 1px dashed var(--archive-line-soft);
    border-radius: 0;
    box-shadow: none;
    transition: color 140ms ease, background-color 140ms ease;
}

#rightNavHolder > [class~="drawer-toggle"] {
    border-right: 1px dashed var(--archive-line-soft);
}

#top-settings-holder [class~="drawer-toggle"]:hover,
#top-settings-holder [class~="drawer-toggle"]:focus-visible {
    color: var(--archive-pink-deep);
    background: var(--archive-pink-soft);
}

#top-settings-holder .drawer-icon {
    color: currentColor;
    font-size: 1.05rem;
    text-shadow: none;
    filter: none;
}

#top-settings-holder .drawer-icon.openIcon {
    color: var(--archive-pink-deep);
}

#ai-config-button > .drawer-toggle::after { content: "档案索引\A 01"; }
#sys-settings-button > .drawer-toggle::after { content: "酿造记录\A 02"; }
#advanced-formatting-button > .drawer-toggle::after { content: "味觉图谱\A 03"; }
#WI-SP-button > .drawer-toggle::after { content: "年份收藏\A 04"; }
#user-settings-button > .drawer-toggle::after { content: "客人简档\A 05"; }
#backgrounds-button > .drawer-toggle::after { content: "事件簿\A 06"; }
#extensions-settings-button > .drawer-toggle::after { content: "封存区\A 07"; }
#persona-management-button > .drawer-toggle::after { content: "检索\A 08"; }
#rightNavHolder > .drawer-toggle::after { content: "笔记\A 09"; }

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > [class~="drawer-toggle"]::after {
    white-space: pre;
    color: currentColor;
    font-family: var(--archive-font-body);
    font-size: clamp(0.42rem, 0.5vw, 0.54rem);
    line-height: 0.94;
    letter-spacing: 0.035em;
    text-align: center;
}

/* ===== src/windows/input.css ===== */
/* 底部无框档案输入栏。 */
#form_sheld {
    margin-top: 0;
    background: var(--archive-mint-10);
}

#send_form {
    width: calc(100% - clamp(1rem, 4vw, 3rem));
    min-height: 0;
    margin: 0 auto 0.45rem;
    position: relative;
    color: var(--archive-ink);
    background: var(--archive-paper-warm);
    border: 0;
    border-radius: 0;
    box-shadow: none;
    backdrop-filter: none;
}

#send_form::before {
    content: none;
}

#nonQRFormItems {
    height: 3.7rem;
    min-height: 3.7rem;
    max-height: 3.7rem;
    flex: 0 0 3.7rem;
    column-gap: 0;
    color: var(--archive-ink);
    font-size: 1.28rem;
}

#leftSendForm,
#rightSendForm {
    align-items: center;
    justify-content: center;
    align-self: stretch;
    flex-wrap: nowrap;
    box-sizing: border-box;
    width: 4.8rem;
    min-width: 4.8rem;
    max-width: 4.8rem;
    flex: 0 0 4.8rem;
    gap: 0.2rem;
    padding: 0.35rem;
}

#leftSendForm {
    order: 1;
    border-right: 0;
}

#rightSendForm {
    order: 3;
    border-left: 0;
}

#leftSendForm > div,
#rightSendForm > div {
    box-sizing: border-box;
    width: 1.75rem;
    height: 2rem;
    min-width: 1.75rem;
    min-height: 2rem;
    max-width: 1.75rem;
    max-height: 2rem;
    flex: 0 0 1.75rem;
    margin: 0;
    padding: 0;
    opacity: 1;
    filter: none;
}

#send_textarea {
    order: 2;
    box-sizing: border-box;
    height: 3.35rem !important;
    min-height: 3.35rem !important;
    max-height: 3.35rem !important;
    min-width: 0;
    flex: 1 1 0;
    padding: 0.65rem 1rem;
