        flex-flow: row nowrap;
        align-items: center;
        column-gap: 0;
        width: 100%;
        height: 4.2rem;
        min-height: 4.2rem;
        max-height: 4.2rem;
        flex: 0 0 4.2rem;
        background: var(--archive-paper-warm);
    }

    #send_form::before,
    #options_button::after,
    #send_but::after {
        content: none;
    }

    #leftSendForm,
    #rightSendForm {
        box-sizing: border-box;
        width: 4.6rem;
        min-width: 4.6rem;
        max-width: 4.6rem;
        height: 4.2rem;
        padding-inline: 0.35rem;
        gap: 0.2rem;
        flex: 0 0 4.6rem;
        flex-wrap: nowrap;
        align-self: stretch;
        align-items: center;
        justify-content: center;
    }

    #leftSendForm {
        order: 1;
    }

    #rightSendForm {
        order: 3;
    }

    #leftSendForm > div,
    #rightSendForm > div {
        box-sizing: border-box;
        width: 1.8rem;
        min-width: 1.8rem;
        max-width: 1.8rem;
        height: 2rem;
        min-height: 2rem;
        max-height: 2rem;
        flex: 0 0 1.8rem;
        margin: 0;
        padding: 0;
        align-items: center;
        justify-content: center;
    }

    #rightSendForm > :is(#send_but, #mes_stop) {
        font-size: 1.3rem;
    }

    #send_textarea {
        display: block;
        order: 2;
        align-self: center;
        box-sizing: border-box;
        width: 100%;
        min-width: 0;
        flex: 1 1 0;
        height: 3.8rem !important;
        min-height: 3.8rem !important;
        max-height: 3.8rem !important;
        padding-inline: 0.7rem;
        background: var(--archive-mint-00);
        border: 0;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel)::before {
        font-size: 0.6em;
        letter-spacing: 0.1em;
    }
}

/* ===== src/fallback.css ===== */
/* 字体与视觉回退：远程字体失败时保持系统宋体/等宽字体，功能不变。 */
:root {
    --archive-font-body-fallback: "Noto Serif CJK SC", "Noto Serif SC", "FangSong", "STFangsong", serif;
    --archive-font-label-fallback: "Courier New", monospace;
}

#chat .mesAvatarWrapper .avatar:not(:has(img)) {
    background: var(--archive-paper);
    border: 1px solid var(--archive-line);
}

@media (prefers-reduced-motion: reduce) {
    #top-bar .drawer-toggle,
    #chat :is(.mes_button, .interactable, .swipe_left, .swipe_right),
    #send_form :is(#send_but, #mes_stop, #options_button, #mes_impersonate, #mes_continue) {
        transition-duration: 0.01ms !important;
    }
}
